{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add pairwise ranking supervision to the existing BCE objective using the same valid sampled pairs. The 0.2-weighted term may improve HR@10 while preserving the architecture, inference, sampling, optimizer, and host-configured 200-epoch cap.",
      "edits": [
        {
          "find": "            loss = bce_criterion(pos_logits[indices], pos_labels)\n            loss = loss + bce_criterion(neg_logits[indices], neg_labels)",
          "replace": "            loss = bce_criterion(pos_logits[indices], pos_labels)\n            loss = loss + bce_criterion(neg_logits[indices], neg_labels)\n            pairwise_loss = nn.functional.softplus(\n                neg_logits[indices] - pos_logits[indices]\n            ).mean()\n            loss = loss + 0.2 * pairwise_loss"
        }
      ]
    }
  ],
  "change_summary": "Add 0.2 times mean softplus(s_neg - s_pos) over valid training positions to the original BCE loss. Predictor and checkpoint formats remain compatible."
}
